def inline(tag):
    s=''.join(str(x) for x in tag.contents)
    s=s.replace('<strong>','<b>').replace('</strong>','</b>').replace('<em>','<i>').replace('</em>','</i>')
    s=re.sub(r'<code>(.*?)</code>',r'<font name="Sans">\1</font>',s,flags=re.S)
    return s
story=[];soup=BeautifulSoup(body,'html.parser')
for tag in soup.children:
    if not getattr(tag,'name',None):continue
    if tag.name in ['h1','h2','h3']:
        if tag.get_text()=='References':story.append(PageBreak())
        story.append(Paragraph(inline(tag),styles[{'h1':'TitleX','h2':'H2X','h3':'H3X'}[tag.name]]))
    elif tag.name=='p':
        cls=tag.get('class',[])
        sty='RefX' if 'reference' in cls else 'TableCaptionX' if 'caption' in cls else 'CaptionX' if 'meta' in cls else 'Article'
        paragraph=Paragraph(inline(tag),styles[sty])
        story.append(KeepTogether([paragraph]) if sty=='RefX' else paragraph)
    elif tag.name=='table':
        rows=[[Paragraph(inline(c),styles['CellX']) for c in tr.find_all(['th','td'])] for tr in tag.find_all('tr')]
        n=len(rows[0]);widths=[495/n]*n
        if n==6: widths=[150,40,60,45,80,120]
        elif n==5:widths=[140,82,55,90,128]
        elif n==4:widths=[156,113,113,113]
        t=Table(rows,colWidths=widths,repeatRows=1,hAlign='LEFT')
        t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e9f1f5')),('LINEBELOW',(0,0),(-1,0),.6,colors.HexColor('#7892a0')),('LINEBELOW',(0,1),(-1,-1),.25,colors.HexColor('#c8d4da')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
        prefix=[]
        if story and isinstance(story[-1],Paragraph) and story[-1].style.name=='TableCaptionX':
            prefix=[story.pop()]
        story.append(KeepTogether(prefix+[t,Spacer(1,12)]))
    elif tag.name=='figure':
        p=(MAN/tag.img['src']).resolve();im=Image(str(p));im.drawHeight=im.imageHeight*495/im.imageWidth;im.drawWidth=495
        story.append(KeepTogether([im,Spacer(1,5),Paragraph(tag.figcaption.get_text(),styles['CaptionX'])]))
